/* umount2(2) - Demonstration of lazy unmount using MNT_DETACH */
#define _GNU_SOURCE
#include <sys/mount.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

/* 
 * NOTE: Running this code requires root privileges (CAP_SYS_ADMIN) 
 * and a valid existing mount point at the target path.
 */
int main(void) {
    const char *target_path = "/mnt/temporary_mount";
    // Use MNT_DETACH flag for lazy unmount
    int flags = MNT_DETACH;
    int ret;

    printf("Attempting lazy unmount (MNT_DETACH) of %s...\n", target_path);

    // Attempt the unmount operation
    ret = umount2(target_path, flags);

    if (ret == 0) {
        printf("Success: Filesystem %s has been lazily detached.\n", target_path);
    } else {
        // Error handling based on errno
        fprintf(stderr, "Error initiating unmount of %s: %s (errno %d)\n",
                target_path, strerror(errno), errno);

        if (errno == EPERM) {
            fprintf(stderr, "Hint: Execution requires root privileges.\n");
        } else if (errno == ENOENT) {
            fprintf(stderr, "Hint: Target path does not exist or is not a mount point.\n");
        }
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
